def search_medrxiv_key_words(key_words, num_results=10, **_extra):
    import json, os, datetime, time, hashlib, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0005000" if __import__("os").path.isdir("./environment_mix/0005000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(client_id, status, tool_name, detail=None):
        # No schema-defined request log collection; record by updating client's daily_requests_used only.
        return

    def _is_nonempty_string(x):
        return isinstance(x, str) and x.strip() != ""

    def _norm_kw(s):
        s = s.strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    def _json_hash(obj):
        b = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        txt = s.strip()
        if not txt:
            return None
        # Accept YYYY-MM-DD or ISO8601 with optional Z
        try:
            if re.fullmatch(r"\d{4}-\d{2}-\d{2}", txt):
                return datetime.datetime.fromisoformat(txt)
            if txt.endswith("Z"):
                txt2 = txt[:-1]
                return datetime.datetime.fromisoformat(txt2)
            return datetime.datetime.fromisoformat(txt)
        except ValueError:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # Load clients and choose a usable "ambient auth" client
    clients = _load("api_clients.json")
    usable_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not usable_clients:
        return _err("UNAUTHORIZED", "No active API client is available to serve this request.")
    # pick a client that can still spend quota (or unlimited)
    chosen = None
    for c in usable_clients:
        lim = c.get("daily_request_limit")
        used = c.get("daily_requests_used")
        if isinstance(lim, int) and isinstance(used, int) and lim >= 0 and used >= 0:
            if lim == 0 or used + 1 <= lim:
                chosen = c
                break
    if chosen is None:
        # Do not create search_requests row per rule; reject.
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for all available API clients.")

    # Validate input
    if not _is_nonempty_string(key_words):
        return _err("VALIDATION_ERROR", "`key_words` must be a non-empty string.")
    if num_results is None:
        num_results = 10
    if not isinstance(num_results, int) or isinstance(num_results, bool):
        return _err("VALIDATION_ERROR", "`num_results` must be an integer.")
    if num_results < 1 or num_results > 200:
        return _err("VALIDATION_ERROR", "`num_results` must be between 1 and 200.")

    normalized = {
        "tool_name": "search_medrxiv_key_words",
        "key_words": _norm_kw(key_words),
    }
    normalized_query_hash = _json_hash(normalized)

    # Enforce uniqueness for in-flight (queued/running) per constraints
    search_requests = _load("search_requests.json")
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") == chosen.get("id") and r.get("normalized_query_hash") == normalized_query_hash and r.get("num_results") == num_results and r.get("status") in ("queued", "running"):
            return _err("CONFLICT", "An identical search is already in progress.", search_request_id=r.get("id"))

    # Spend quota now (observable dynamics); if save fails later, we still won't mask errors, but must not raise.
    chosen["daily_requests_used"] = int(chosen.get("daily_requests_used", 0)) + 1
    chosen["updated_at"] = now
    _save("api_clients.json", clients)

    # Cache check: identical normalized_query_hash+num_results succeeded within TTL
    TTL_SECONDS = 6 * 60 * 60  # 6 hours
    cache_hit_req = None
    cache_hit_time = None
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != chosen.get("id"):
            continue
        if r.get("normalized_query_hash") != normalized_query_hash:
            continue
        if r.get("num_results") != num_results:
            continue
        if r.get("status") != "succeeded":
            continue
        finished_at = _parse_dt(r.get("finished_at"))
        if finished_at is None:
            continue
        age = (datetime.datetime.utcnow() - finished_at).total_seconds()
        if age <= TTL_SECONDS:
            if cache_hit_time is None or finished_at > cache_hit_time:
                cache_hit_time = finished_at
                cache_hit_req = r

    preprints = _load("preprints.json")
    search_results = _load("search_results.json")

    def _preprint_by_id(pid):
        for p in preprints:
            if isinstance(p, dict) and p.get("id") == pid:
                return p
        return None

    def _result_payload_for_request(req_id, n):
        rows = [sr for sr in search_results if isinstance(sr, dict) and sr.get("search_request_id") == req_id]
        rows.sort(key=lambda x: x.get("rank", 10**9))
        out = []
        for sr in rows[:n]:
            p = _preprint_by_id(sr.get("preprint_id"))
            if not p:
                continue
            out.append({
                "rank": sr.get("rank"),
                "score": sr.get("score"),
                "snippet": sr.get("snippet"),
                "preprint": {
                    "id": p.get("id"),
                    "doi": p.get("doi"),
                    "server": p.get("server"),
                    "title": p.get("title"),
                    "abstract": p.get("abstract"),
                    "authors": p.get("authors"),
                    "author_corresponding": p.get("author_corresponding"),
                    "author_corresponding_institution": p.get("author_corresponding_institution"),
                    "category": p.get("category"),
                    "version": p.get("version"),
                    "posted_date": p.get("posted_date"),
                    "published_journal": p.get("published_journal"),
                    "published_date": p.get("published_date"),
                    "license": p.get("license"),
                    "url": p.get("url"),
                    "pdf_url": p.get("pdf_url"),
                    "status": p.get("status"),
                    "metadata_fetched_at": p.get("metadata_fetched_at"),
                    "created_at": p.get("created_at"),
                    "updated_at": p.get("updated_at"),
                }
            })
        return out

    # Create search request
    req_id = _gen_id("srch")
    req_row = {
        "id": req_id,
        "client_id": chosen.get("id"),
        "tool_name": "search_medrxiv_key_words",
        "key_words": key_words,
        "term": None,
        "title": None,
        "author1": None,
        "author2": None,
        "abstract_title": None,
        "text_abstract_title": None,
        "section": None,
        "start_date": None,
        "end_date": None,
        "num_results": num_results,
        "normalized_query_hash": normalized_query_hash,
        "status": "queued",
        "upstream_cache_hit": False,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # If cache hit, we can complete immediately by reusing results.
    if cache_hit_req is not None:
        req_row["status"] = "running"
        req_row["started_at"] = now
        req_row["updated_at"] = now
        search_requests.append(req_row)
        _save("search_requests.json", search_requests)

        # Reuse existing results/preprints; do not duplicate search_results rows (they are tied to request id),
        # but business rule expects rows for each successful request; we must create new rows referencing same preprints.
        cached_req_id = cache_hit_req.get("id")
        cached_rows = [sr for sr in search_results if isinstance(sr, dict) and sr.get("search_request_id") == cached_req_id]
        cached_rows.sort(key=lambda x: x.get("rank", 10**9))
        new_rows = []
        seen_pp = set()
        rank = 1
        for sr in cached_rows:
            if rank > num_results:
                break
            pid = sr.get("preprint_id")
            if pid in seen_pp:
                continue
            p = _preprint_by_id(pid)
            if not p or p.get("status") == "tombstoned":
                continue
            seen_pp.add(pid)
            new_rows.append({
                "id": _gen_id("sres"),
                "search_request_id": req_id,
                "preprint_id": pid,
                "rank": rank,
                "score": sr.get("score"),
                "snippet": sr.get("snippet"),
                "created_at": now,
                "updated_at": now,
            })
            rank += 1

        if len(new_rows) == 0:
            # No success without effect: cannot claim succeeded with zero results.
            # Mark failed.
            for r in search_requests:
                if isinstance(r, dict) and r.get("id") == req_id:
                    r["status"] = "failed"
                    r["error_message"] = "Cache entry existed but produced no usable results."
                    r["finished_at"] = now
                    r["updated_at"] = now
                    r["upstream_cache_hit"] = True
                    break
            _save("search_requests.json", search_requests)
            return _err("NOT_FOUND", "No results available for this query (cache contained no usable results).", search_request_id=req_id)

        req_row_update = None
        for r in search_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                req_row_update = r
                break
        if req_row_update:
            req_row_update["status"] = "succeeded"
            req_row_update["upstream_cache_hit"] = True
            req_row_update["finished_at"] = now
            req_row_update["updated_at"] = now
        search_results.extend(new_rows)
        _save("search_results.json", search_results)
        _save("search_requests.json", search_requests)

        data = _result_payload_for_request(req_id, num_results)
        return {
            "search_request": {
                "id": req_id,
                "status": "succeeded",
                "upstream_cache_hit": True,
                "num_results": num_results,
                "normalized_query_hash": normalized_query_hash,
                "created_at": req_row_update.get("created_at") if req_row_update else now,
                "finished_at": now,
            },
            "results": data,
            "meta": {
                "returned": len(data),
                "requested": num_results,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        }

    # Not a cache hit: execute "upstream" search using local preprints store heuristics.
    req_row["status"] = "running"
    req_row["started_at"] = now
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    # Simple local search: match keywords against title/abstract/authors/category/doi
    kw = _norm_kw(key_words)
    terms = [t for t in re.split(r"[^\w/]+", kw) if t]
    def _text(p):
        parts = []
        for k in ("doi", "title", "abstract", "category", "published_journal", "license", "url"):
            v = p.get(k)
            if isinstance(v, str) and v:
                parts.append(v.lower())
        a = p.get("authors")
        if isinstance(a, list):
            parts.append(" ".join([str(x).lower() for x in a if isinstance(x, str)]))
        return " ".join(parts)

    candidates = []
    for p in preprints:
        if not isinstance(p, dict):
            continue
        if p.get("status") == "tombstoned":
            continue
        if p.get("server") not in ("medrxiv", "biorxiv"):
            continue
        txt = _text(p)
        if not txt:
            continue
        score = 0
        for t in terms:
            if t in txt:
                score += 1
        if score > 0:
            # Prefer medrxiv when tied, and newer posted_date
            posted = _parse_dt(p.get("posted_date"))
            candidates.append((score, 1 if p.get("server") == "medrxiv" else 0, posted or datetime.datetime(1970, 1, 1), p))

    candidates.sort(key=lambda x: (x[0], x[1], x[2]), reverse=True)

    picked = []
    seen_doi = set()
    for score, _, __, p in candidates:
        if len(picked) >= num_results:
            break
        doi = p.get("doi")
        if doi in seen_doi:
            continue
        seen_doi.add(doi)
        picked.append((p, float(score)))

    # If no candidates, fail (no success without effect)
    if len(picked) == 0:
        for r in search_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "No matching preprints found in local cache."
                r["finished_at"] = now
                r["updated_at"] = now
                break
        _save("search_requests.json", search_requests)
        return {
            "search_request": {
                "id": req_id,
                "status": "failed",
                "upstream_cache_hit": False,
                "num_results": num_results,
                "normalized_query_hash": normalized_query_hash,
                "created_at": req_row.get("created_at"),
                "finished_at": now,
                "error_message": "No matching preprints found in local cache.",
            },
            "results": [],
            "meta": {
                "returned": 0,
                "requested": num_results,
                "latency_ms": int((time.time() - t0) * 1000),
            }
        }

    # Create contiguous ranked search_results rows
    new_rows = []
    rank = 1
    for p, score in picked:
        new_rows.append({
            "id": _gen_id("sres"),
            "search_request_id": req_id,
            "preprint_id": p.get("id"),
            "rank": rank,
            "score": score,
            "snippet": None,
            "created_at": now,
            "updated_at": now,
        })
        rank += 1

    search_results.extend(new_rows)
    _save("search_results.json", search_results)

    for r in search_requests:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = "succeeded"
            r["finished_at"] = now
            r["updated_at"] = now
            r["upstream_cache_hit"] = False
            break
    _save("search_requests.json", search_requests)

    data = _result_payload_for_request(req_id, num_results)
    return {
        "search_request": {
            "id": req_id,
            "status": "succeeded",
            "upstream_cache_hit": False,
            "num_results": num_results,
            "normalized_query_hash": normalized_query_hash,
            "created_at": req_row.get("created_at"),
            "finished_at": now,
        },
        "results": data,
        "meta": {
            "returned": len(data),
            "requested": num_results,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def search_medrxiv_advanced(term=None, title=None, author1=None, author2=None, abstract_title=None, text_abstract_title=None, section=None, start_date=None, end_date=None, num_results=10, **_extra):
    import json, os, datetime, time, hashlib, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0005000" if __import__("os").path.isdir("./environment_mix/0005000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _audit(client_id, credential, http_status, error_code=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "search_medrxiv_advanced",
            "tool_name": "search_medrxiv_advanced",
            "client_id": client_id,
            "credential": credential,
            "status": http_status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    def _parse_dt_to_isoz(s, field_name):
        if s is None:
            return None, None
        if isinstance(s, bool) or not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an ISO-8601 string or null", field=field_name)
        txt = s.strip()
        if not txt:
            return None, None
        try:
            if txt.endswith("Z"):
                dt = datetime.datetime.fromisoformat(txt[:-1])
            else:
                dt = datetime.datetime.fromisoformat(txt)
            return dt.replace(microsecond=0).isoformat() + "Z", None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a valid ISO-8601 datetime string", field=field_name)

    def _norm_text(s):
        if s is None:
            return None
        if isinstance(s, bool) or not isinstance(s, str):
            return None
        s2 = re.sub(r"\s+", " ", s.strip().lower())
        return s2 if s2 else None

    def _json_hash(obj):
        b = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return "qhash_" + hashlib.sha256(b).hexdigest()[:40]

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # ---- Input validation (tool schema) ----
    for fn, val in [
        ("term", term), ("title", title), ("author1", author1), ("author2", author2),
        ("abstract_title", abstract_title), ("text_abstract_title", text_abstract_title),
        ("section", section)
    ]:
        if val is not None and (isinstance(val, bool) or not isinstance(val, str)):
            _audit(None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{fn} must be a string or null", field=fn)

    if num_results is None:
        num_results = 10
    if isinstance(num_results, bool) or not isinstance(num_results, int):
        _audit(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "num_results must be an integer", field="num_results")
    if num_results < 1 or num_results > 200:
        _audit(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 200", field="num_results")

    start_iso, e1 = _parse_dt_to_isoz(start_date, "start_date")
    if e1:
        _audit(None, None, 400, e1["error"]["code"])
        return e1
    end_iso, e2 = _parse_dt_to_isoz(end_date, "end_date")
    if e2:
        _audit(None, None, 400, e2["error"]["code"])
        return e2

    # Advanced requirement: accept all-null fields by creating a FAILED request (per business rules tolerance).
    has_any_field = any([
        _norm_text(term), _norm_text(title), _norm_text(author1), _norm_text(author2),
        _norm_text(abstract_title), _norm_text(text_abstract_title), _norm_text(section),
        start_iso is not None, end_iso is not None
    ])

    # Ambient auth: resolve an active client that is not quota-exceeded.
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    chosen = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("status") != "active":
            continue
        limit = c.get("daily_request_limit")
        used = c.get("daily_requests_used")
        if not isinstance(limit, int) or limit < 0:
            continue
        if not isinstance(used, int) or used < 0:
            used = 0
        if limit > 0 and (used + 1) > limit:
            continue
        chosen = c
        break
    if not chosen:
        _audit(None, None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API client available (all suspended/deleted or quota exhausted).")

    client_id = chosen.get("id")
    credential_used = client_id  # ambient

    # Enforce quota: increment daily_requests_used for chosen client for this call.
    limit = chosen.get("daily_request_limit")
    used = chosen.get("daily_requests_used")
    if not isinstance(used, int) or used < 0:
        used = 0
    if isinstance(limit, int) and limit > 0 and (used + 1) > limit:
        _audit(client_id, credential_used, 429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_request_limit=limit, daily_requests_used=used)
    # persist increment
    for i, c in enumerate(clients):
        if isinstance(c, dict) and c.get("id") == client_id:
            c["daily_requests_used"] = used + 1
            c["updated_at"] = now
            clients[i] = c
            _save("api_clients.json", clients)
            break

    # ---- Create search request row (queued->running->final) ----
    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []

    normalized_payload = {
        "tool_name": "search_medrxiv_advanced",
        "term": _norm_text(term),
        "title": _norm_text(title),
        "author1": _norm_text(author1),
        "author2": _norm_text(author2),
        "abstract_title": _norm_text(abstract_title),
        "text_abstract_title": _norm_text(text_abstract_title),
        "section": _norm_text(section),
        "start_date": start_iso,
        "end_date": end_iso,
    }
    nqhash = _json_hash({"p": normalized_payload, "num_results": num_results})

    # Find cache hit: previously succeeded with same hash + num_results within TTL.
    TTL_SECONDS = 6 * 60 * 60
    cache_hit_req = None
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        if r.get("status") != "succeeded":
            continue
        if r.get("normalized_query_hash") != nqhash:
            continue
        if r.get("num_results") != num_results:
            continue
        finished = r.get("finished_at") or r.get("updated_at")
        if isinstance(finished, str):
            try:
                if finished.endswith("Z"):
                    fdt = datetime.datetime.fromisoformat(finished[:-1])
                else:
                    fdt = datetime.datetime.fromisoformat(finished)
                age = (now_dt - fdt).total_seconds()
                if 0 <= age <= TTL_SECONDS:
                    cache_hit_req = r
                    break
            except ValueError:
                pass

    sreq_id = _gen_id("mrx_sreq")
    sreq_row = {
        "id": sreq_id,
        "client_id": client_id,
        "tool_name": "search_medrxiv_advanced",
        "key_words": None,
        "term": term,
        "title": title,
        "author1": author1,
        "author2": author2,
        "abstract_title": abstract_title,
        "text_abstract_title": text_abstract_title,
        "section": section,
        "start_date": start_iso,
        "end_date": end_iso,
        "num_results": num_results,
        "normalized_query_hash": nqhash,
        "status": "queued",
        "upstream_cache_hit": bool(cache_hit_req),
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }

    # Uniqueness constraint for queued/running (client_id, normalized_query_hash, num_results)
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") == client_id and r.get("normalized_query_hash") == nqhash and r.get("num_results") == num_results and r.get("status") in ("queued", "running"):
            # Idempotent-ish: return existing in-flight request (no new mutation)
            sreq_id = r.get("id")
            sreq = r
            # build response from existing rows if any
            results_rows = _load("search_results.json")
            if not isinstance(results_rows, list):
                results_rows = []
            preprints = _load("preprints.json")
            if not isinstance(preprints, list):
                preprints = []
            # join
            res = [x for x in results_rows if isinstance(x, dict) and x.get("search_request_id") == sreq_id]
            res.sort(key=lambda x: x.get("rank", 10**9))
            pre_by_id = {p.get("id"): p for p in preprints if isinstance(p, dict)}
            items = []
            for rr in res[:num_results]:
                pp = pre_by_id.get(rr.get("preprint_id"))
                if not isinstance(pp, dict):
                    continue
                items.append({
                    "rank": rr.get("rank"),
                    "score": rr.get("score"),
                    "snippet": rr.get("snippet"),
                    "preprint": pp
                })
            _audit(client_id, credential_used, 200, None)
            return {
                "search_request": sreq,
                "results": items,
                "num_results": num_results,
                "returned": len(items),
                "cache_hit": bool(sreq.get("upstream_cache_hit"))
            }

    # append queued row
    search_requests.append(sreq_row)
    _save("search_requests.json", search_requests)

    # transition queued -> running
    for i, r in enumerate(search_requests):
        if isinstance(r, dict) and r.get("id") == sreq_id:
            r["status"] = "running"
            r["started_at"] = now
            r["updated_at"] = now
            search_requests[i] = r
            _save("search_requests.json", search_requests)
            break

    # Handle invalid request semantics by marking failed (rather than rejecting tool call).
    if not has_any_field:
        msg = "At least one advanced search field must be provided."
        for i, r in enumerate(search_requests):
            if isinstance(r, dict) and r.get("id") == sreq_id:
                r["status"] = "failed"
                r["error_message"] = msg
                r["finished_at"] = now
                r["updated_at"] = now
                search_requests[i] = r
                _save("search_requests.json", search_requests)
                break
        _audit(client_id, credential_used, 200, None)
        return {
            "search_request": next((r for r in search_requests if isinstance(r, dict) and r.get("id") == sreq_id), sreq_row),
            "results": [],
            "num_results": num_results,
            "returned": 0,
            "cache_hit": False
        }

    # Date range validation: if invalid, fail request (per business rules).
    if start_iso is not None and end_iso is not None:
        try:
            sdt = datetime.datetime.fromisoformat(start_iso[:-1]) if start_iso.endswith("Z") else datetime.datetime.fromisoformat(start_iso)
            edt = datetime.datetime.fromisoformat(end_iso[:-1]) if end_iso.endswith("Z") else datetime.datetime.fromisoformat(end_iso)
            if sdt > edt:
                msg = "Invalid date range: start_date is after end_date"
                for i, r in enumerate(search_requests):
                    if isinstance(r, dict) and r.get("id") == sreq_id:
                        r["status"] = "failed"
                        r["error_message"] = msg
                        r["finished_at"] = now
                        r["updated_at"] = now
                        search_requests[i] = r
                        _save("search_requests.json", search_requests)
                        break
                _audit(client_id, credential_used, 200, None)
                return {
                    "search_request": next((r for r in search_requests if isinstance(r, dict) and r.get("id") == sreq_id), sreq_row),
                    "results": [],
                    "num_results": num_results,
                    "returned": 0,
                    "cache_hit": False
                }
        except ValueError:
            # If parse fails despite earlier validation, treat as failure.
            msg = "Invalid date range values"
            for i, r in enumerate(search_requests):
                if isinstance(r, dict) and r.get("id") == sreq_id:
                    r["status"] = "failed"
                    r["error_message"] = msg
                    r["finished_at"] = now
                    r["updated_at"] = now
                    search_requests[i] = r
                    _save("search_requests.json", search_requests)
                    break
            _audit(client_id, credential_used, 200, None)
            return {
                "search_request": next((r for r in search_requests if isinstance(r, dict) and r.get("id") == sreq_id), sreq_row),
                "results": [],
                "num_results": num_results,
                "returned": 0,
                "cache_hit": False
            }

    # If cache hit, reuse existing search_results/preprints and mark succeeded.
    if cache_hit_req:
        cached_id = cache_hit_req.get("id")
        sr = _load("search_results.json")
        if not isinstance(sr, list):
            sr = []
        cached_results = [x for x in sr if isinstance(x, dict) and x.get("search_request_id") == cached_id]
        cached_results.sort(key=lambda x: x.get("rank", 10**9))
        # Copy result rows to new request id, preserving ranks, ensuring uniqueness.
        new_rows = []
        seen_pp = set()
        used_ranks = set()
        for rr in cached_results:
            rk = rr.get("rank")
            pp_id = rr.get("preprint_id")
            if not isinstance(rk, int) or rk < 1:
                continue
            if rk in used_ranks:
                continue
            if not isinstance(pp_id, str) or not pp_id:
                continue
            if pp_id in seen_pp:
                continue
            if rk > num_results:
                continue
            used_ranks.add(rk)
            seen_pp.add(pp_id)
            new_rows.append({
                "id": _gen_id("mrx_sres"),
                "search_request_id": sreq_id,
                "preprint_id": pp_id,
                "rank": rk,
                "score": rr.get("score"),
                "snippet": rr.get("snippet"),
                "created_at": now,
                "updated_at": now
            })
        # ensure contiguous 1..k
        new_rows.sort(key=lambda x: x["rank"])
        if new_rows and [r["rank"] for r in new_rows] != list(range(1, len(new_rows) + 1)):
            # re-rank contiguously
            for idx, r in enumerate(new_rows, start=1):
                r["rank"] = idx
                r["updated_at"] = now

        sr.extend(new_rows)
        _save("search_results.json", sr)

        # mark succeeded
        search_requests = _load("search_requests.json")
        if not isinstance(search_requests, list):
            search_requests = []
        for i, r in enumerate(search_requests):
            if isinstance(r, dict) and r.get("id") == sreq_id:
                r["status"] = "succeeded"
                r["finished_at"] = now
                r["updated_at"] = now
                r["upstream_cache_hit"] = True
                search_requests[i] = r
                _save("search_requests.json", search_requests)
                sreq_row = r
                break

        preprints = _load("preprints.json")
        if not isinstance(preprints, list):
            preprints = []
        pre_by_id = {p.get("id"): p for p in preprints if isinstance(p, dict)}
        items = []
        for rr in new_rows:
            pp = pre_by_id.get(rr.get("preprint_id"))
            if not isinstance(pp, dict):
                continue
            items.append({"rank": rr.get("rank"), "score": rr.get("score"), "snippet": rr.get("snippet"), "preprint": pp})
        items.sort(key=lambda x: x.get("rank", 10**9))
        _audit(client_id, credential_used, 200, None)
        return {"search_request": sreq_row, "results": items, "num_results": num_results, "returned": len(items), "cache_hit": True}

    # Otherwise, produce results from local preprints store (offline stand-in for upstream).
    preprints = _load("preprints.json")
    if not isinstance(preprints, list):
        preprints = []

    def _matches(pp):
        if not isinstance(pp, dict):
            return False
        if pp.get("status") == "tombstoned":
            return False  # exclude tombstoned from new results
        hay = " ".join([
            str(pp.get("doi") or ""),
            str(pp.get("title") or ""),
            str(pp.get("abstract") or ""),
            " ".join(pp.get("authors") or []) if isinstance(pp.get("authors"), list) else ""
        ]).lower()
        for val in [_norm_text(term), _norm_text(title), _norm_text(abstract_title), _norm_text(text_abstract_title), _norm_text(author1), _norm_text(author2), _norm_text(section)]:
            if val and val not in hay:
                return False
        # date range filter against posted_date if present
        pd = pp.get("posted_date")
        if (start_iso or end_iso) and isinstance(pd, str):
            try:
                pdt = datetime.datetime.fromisoformat(pd[:-1]) if pd.endswith("Z") else datetime.datetime.fromisoformat(pd)
                if start_iso:
                    sdt = datetime.datetime.fromisoformat(start_iso[:-1]) if start_iso.endswith("Z") else datetime.datetime.fromisoformat(start_iso)
                    if pdt < sdt:
                        return False
                if end_iso:
                    edt = datetime.datetime.fromisoformat(end_iso[:-1]) if end_iso.endswith("Z") else datetime.datetime.fromisoformat(end_iso)
                    if pdt > edt:
                        return False
            except ValueError:
                pass
        return True

    candidates = [pp for pp in preprints if _matches(pp)]
    # deterministic ordering: most recent posted_date/updated_at first, then doi
    def _sort_key(pp):
        ts = pp.get("posted_date") or pp.get("updated_at") or pp.get("created_at") or ""
        return (ts, pp.get("doi") or "")
    candidates.sort(key=_sort_key, reverse=True)

    picked = candidates[:num_results]
    if not picked:
        # still succeed with 0 results (allowed)
        search_requests = _load("search_requests.json")
        if not isinstance(search_requests, list):
            search_requests = []
        for i, r in enumerate(search_requests):
            if isinstance(r, dict) and r.get("id") == sreq_id:
                r["status"] = "succeeded"
                r["finished_at"] = now
                r["updated_at"] = now
                search_requests[i] = r
                _save("search_requests.json", search_requests)
                sreq_row = r
                break
        _audit(client_id, credential_used, 200, None)
        return {"search_request": sreq_row, "results": [], "num_results": num_results, "returned": 0, "cache_hit": False}

    # Create search_results rows with contiguous ranks and no duplicate preprint_id.
    search_results = _load("search_results.json")
    if not isinstance(search_results, list):
        search_results = []
    seen = set()
    created_rows = []
    rank = 1
    for pp in picked:
        pp_id = pp.get("id")
        if not isinstance(pp_id, str) or not pp_id:
            continue
        if pp_id in seen:
            continue
        seen.add(pp_id)
        created_rows.append({
            "id": _gen_id("mrx_sres"),
            "search_request_id": sreq_id,
            "preprint_id": pp_id,
            "rank": rank,
            "score": None,
            "snippet": None,
            "created_at": now,
            "updated_at": now
        })
        rank += 1
        if rank > num_results:
            break

    # persist created rows
    search_results.extend(created_rows)
    _save("search_results.json", search_results)

    # mark succeeded
    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []
    for i, r in enumerate(search_requests):
        if isinstance(r, dict) and r.get("id") == sreq_id:
            r["status"] = "succeeded"
            r["finished_at"] = now
            r["updated_at"] = now
            r["upstream_cache_hit"] = False
            search_requests[i] = r
            _save("search_requests.json", search_requests)
            sreq_row = r
            break

    items = [{"rank": rr["rank"], "score": rr.get("score"), "snippet": rr.get("snippet"), "preprint": picked[rr["rank"] - 1]} for rr in created_rows if 1 <= rr["rank"] <= len(picked)]
    items.sort(key=lambda x: x.get("rank", 10**9))
    _audit(client_id, credential_used, 200, None)
    return {"search_request": sreq_row, "results": items, "num_results": num_results, "returned": len(items), "cache_hit": False}

def get_medrxiv_metadata(doi, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0005000" if __import__("os").path.isdir("./environment_mix/0005000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        txt = s.strip()
        if not txt:
            return None
        try:
            if txt.endswith("Z"):
                return datetime.datetime.fromisoformat(txt[:-1])
            return datetime.datetime.fromisoformat(txt)
        except ValueError:
            return None

    def _doi_ok(s):
        return isinstance(s, str) and "/" in s.strip()

    # Ambient auth & quota
    clients = _load("api_clients.json")
    usable = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    if not usable:
        return _err("UNAUTHORIZED", "No active API client is available to serve this request.")
    chosen = None
    for c in usable:
        lim = c.get("daily_request_limit")
        used = c.get("daily_requests_used")
        if isinstance(lim, int) and isinstance(used, int) and lim >= 0 and used >= 0:
            if lim == 0 or used + 1 <= lim:
                chosen = c
                break
    if chosen is None:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for all available API clients.")

    # Validate DOI
    if not _doi_ok(doi):
        return _err("VALIDATION_ERROR", "`doi` must be a non-empty string containing '/'.")
    doi_norm = doi.strip()

    # Spend quota
    chosen["daily_requests_used"] = int(chosen.get("daily_requests_used", 0)) + 1
    chosen["updated_at"] = now
    _save("api_clients.json", clients)

    doi_requests = _load("doi_metadata_requests.json")
    # In-flight uniqueness
    for r in doi_requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") == chosen.get("id") and r.get("doi") == doi_norm and r.get("status") in ("queued", "running"):
            return _err("CONFLICT", "A metadata request for this DOI is already in progress.", doi_metadata_request_id=r.get("id"))

    req_id = _gen_id("dreq")
    req_row = {
        "id": req_id,
        "client_id": chosen.get("id"),
        "doi": doi_norm,
        "preprint_id": None,
        "status": "queued",
        "cache_hit": False,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    # Transition to running
    req_row["status"] = "running"
    req_row["started_at"] = now
    req_row["updated_at"] = now
    doi_requests.append(req_row)
    _save("doi_metadata_requests.json", doi_requests)

    preprints = _load("preprints.json")

    def _find_preprint_by_doi(d):
        for p in preprints:
            if isinstance(p, dict) and p.get("doi") == d:
                return p
        return None

    p = _find_preprint_by_doi(doi_norm)

    # Metadata freshness TTL
    TTL_SECONDS = 24 * 60 * 60  # 24 hours
    if p is not None and p.get("status") != "tombstoned":
        fetched_at = _parse_dt(p.get("metadata_fetched_at"))
        if fetched_at is not None:
            age = (now_dt - fetched_at).total_seconds()
            if age <= TTL_SECONDS:
                # Cache hit
                for r in doi_requests:
                    if isinstance(r, dict) and r.get("id") == req_id:
                        r["status"] = "succeeded"
                        r["cache_hit"] = True
                        r["preprint_id"] = p.get("id")
                        r["finished_at"] = now
                        r["updated_at"] = now
                        break
                _save("doi_metadata_requests.json", doi_requests)
                return {
                    "doi_metadata_request": {
                        "id": req_id,
                        "status": "succeeded",
                        "cache_hit": True,
                        "doi": doi_norm,
                        "preprint_id": p.get("id"),
                        "finished_at": now,
                    },
                    "preprint": p,
                    "meta": {"latency_ms": int((time.time() - t0) * 1000)}
                }

    # "Upstream" resolution: offline mode only. We can only succeed if present in store; otherwise NOT_FOUND.
    # If present but stale, we "refetch" by bumping metadata_fetched_at and updated_at (normalized refresh).
    if p is None:
        # Not found => terminal not_found
        for r in doi_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "not_found"
                r["cache_hit"] = False
                r["finished_at"] = now
                r["updated_at"] = now
                break
        _save("doi_metadata_requests.json", doi_requests)
        return _err("NOT_FOUND", "DOI did not resolve to a cached medRxiv/bioRxiv preprint in this offline datastore.", doi=doi_norm, doi_metadata_request_id=req_id)

    # Refresh existing record (upsert semantics: reference existing DOI row)
    if p.get("status") == "tombstoned":
        # Treat as not found for new fetches (logical delete rule)
        for r in doi_requests:
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "not_found"
                r["cache_hit"] = False
                r["finished_at"] = now
                r["updated_at"] = now
                break
        _save("doi_metadata_requests.json", doi_requests)
        return _err("NOT_FOUND", "DOI refers to a tombstoned preprint record.", doi=doi_norm, doi_metadata_request_id=req_id)

    # Update freshness markers
    p["metadata_fetched_at"] = now
    p["updated_at"] = now
    if p.get("created_at") is None:
        p["created_at"] = now

    _save("preprints.json", preprints)

    for r in doi_requests:
        if isinstance(r, dict) and r.get("id") == req_id:
            r["status"] = "succeeded"
            r["cache_hit"] = False
            r["preprint_id"] = p.get("id")
            r["finished_at"] = now
            r["updated_at"] = now
            break
    _save("doi_metadata_requests.json", doi_requests)

    return {
        "doi_metadata_request": {
            "id": req_id,
            "status": "succeeded",
            "cache_hit": False,
            "doi": doi_norm,
            "preprint_id": p.get("id"),
            "finished_at": now,
        },
        "preprint": p,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def get_current_api_client(api_key, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0005000" if __import__("os").path.isdir("./environment_mix/0005000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(api_key, str) or api_key.strip() == "":
        return _err("UNAUTHORIZED", "API key is missing or invalid.")
    presented = api_key.strip()

    clients = _load("api_clients.json")
    matched = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        # Per contract: authenticate by matching client-visible value or id; hashes cannot be checked.
        if c.get("id") == presented:
            matched = c
            break
        # Allow deployments that store plaintext in api_key_hash field (despite name) by matching exact value.
        if isinstance(c.get("api_key_hash"), str) and c.get("api_key_hash") == presented:
            matched = c
            break
        # Also allow matching by name for local dev convenience if api_key is a known identifier.
        if c.get("name") == presented:
            matched = c
            break

    if matched is None:
        return _err("UNAUTHORIZED", "API key is missing or invalid.")

    if matched.get("status") == "suspended":
        return _err("UNAUTHORIZED", "Client is suspended.")
    if matched.get("status") == "deleted":
        return _err("UNAUTHORIZED", "Client is deleted.")

    # Observable dynamics: count this call against quota, since schema tracks daily_requests_used.
    lim = matched.get("daily_request_limit")
    used = matched.get("daily_requests_used")
    if isinstance(lim, int) and isinstance(used, int) and lim > 0 and used + 1 > lim:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
    if isinstance(used, int):
        matched["daily_requests_used"] = used + 1
    else:
        matched["daily_requests_used"] = 1
    matched["updated_at"] = now
    _save("api_clients.json", clients)

    return {
        "client": {
            "id": matched.get("id"),
            "name": matched.get("name"),
            "status": matched.get("status"),
            "daily_request_limit": matched.get("daily_request_limit"),
            "daily_requests_used": matched.get("daily_requests_used"),
            "created_at": matched.get("created_at"),
            "updated_at": matched.get("updated_at"),
            "scopes": ["search", "metadata"],  # not in schema; returned as typical vendor field
        },
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def list_search_requests(api_key, status=None, tool_name=None, normalized_query_hash=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0005000" if __import__("os").path.isdir("./environment_mix/0005000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _audit(client_id, credential, http_status, error_code=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "list_search_requests",
            "tool_name": "list_search_requests",
            "client_id": client_id,
            "credential": credential,
            "status": http_status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _audit(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if status is not None and status not in ("queued", "running", "succeeded", "failed"):
        _audit(None, api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed", field="status")
    if tool_name is not None and tool_name not in ("search_medrxiv_key_words", "search_medrxiv_advanced"):
        _audit(None, api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tool_name must be one of: search_medrxiv_key_words, search_medrxiv_advanced", field="tool_name")
    if normalized_query_hash is not None and (not isinstance(normalized_query_hash, str) or not normalized_query_hash.strip()):
        _audit(None, api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "normalized_query_hash must be a non-empty string when provided", field="normalized_query_hash")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        _audit(None, api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _audit(None, api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100", field="page_size")

    # Authenticate: api_key matches api_clients.id OR api_clients.api_key_hash (client-visible in this datastore)
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    api_key_s = api_key.strip()
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key_s or c.get("api_key_hash") == api_key_s:
            client = c
            break
    if not client:
        _audit(None, api_key_s, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid credentials.")
    if client.get("status") in ("suspended", "deleted"):
        _audit(client.get("id"), api_key_s, 403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", f"Client is {client.get('status')} and cannot perform this operation.")

    # Quota (counts reads too)
    limit = client.get("daily_request_limit")
    used = client.get("daily_requests_used")
    if not isinstance(limit, int) or limit < 0:
        _audit(client.get("id"), api_key_s, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Client daily_request_limit is invalid.")
    if not isinstance(used, int) or used < 0:
        used = 0
    if limit > 0 and (used + 1) > limit:
        _audit(client.get("id"), api_key_s, 429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_request_limit=limit, daily_requests_used=used)
    for i, c in enumerate(clients):
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["daily_requests_used"] = used + 1
            c["updated_at"] = now
            clients[i] = c
            _save("api_clients.json", clients)
            break

    # Filter rows
    rows = _load("search_requests.json")
    if not isinstance(rows, list):
        rows = []
    cid = client.get("id")
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != cid:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if normalized_query_hash is not None and r.get("normalized_query_hash") != normalized_query_hash:
            continue
        out.append(r)

    # Sort reverse-chronological (created_at, then id)
    out.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""), reverse=True)

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = out[start:end]
    has_more = end < total

    _audit(client.get("id"), api_key_s, 200, None)
    return {
        "items": page_rows,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more
    }

def get_search_request(api_key, search_request_id, include_results=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0005000" if __import__("os").path.isdir("./environment_mix/0005000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_request_logs():
        p = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(p):
            _save("request_logs.json", [])

    def _audit(client_id, credential, http_status, error_code=None, meta=None):
        _ensure_request_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "get_search_request",
            "tool_name": "get_search_request",
            "client_id": client_id,
            "credential": credential,
            "status": http_status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # ---- validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        _audit(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        _audit(None, api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string", field="search_request_id")
    if include_results is None:
        include_results = False
    if not isinstance(include_results, bool):
        _audit(None, api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_results must be a boolean", field="include_results")

    # ---- authenticate client by api_key (match by stored client-visible value OR id) ----
    clients = _load("api_clients.json")
    if isinstance(clients, dict) and isinstance(clients.get("rows"), list):
        clients_rows = clients.get("rows")
    elif isinstance(clients, list):
        clients_rows = clients
    else:
        clients_rows = []

    authed_client = None
    for c in clients_rows:
        if not isinstance(c, dict):
            continue
        # IMPORTANT: do NOT compare against hash of an unknown plaintext; accept direct match to stored value or id
        if api_key == c.get("id") or api_key == c.get("api_key_hash"):
            if c.get("status") == "active":
                authed_client = c
                break

    if authed_client is None:
        # Could also be because matched suspended/deleted; distinguish per spec
        for c in clients_rows:
            if not isinstance(c, dict):
                continue
            if api_key == c.get("id") or api_key == c.get("api_key_hash"):
                if c.get("status") in ("suspended", "deleted"):
                    _audit(c.get("id"), api_key, 403, "UNAUTHORIZED", meta={"client_status": c.get("status")})
                    return _err("UNAUTHORIZED", "Client is not permitted (suspended/deleted).", client_status=c.get("status"))
        _audit(None, api_key, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    client_id = authed_client.get("id")

    # ---- quota enforcement (daily_request_limit) ----
    # This endpoint is a request too; increment usage only on allowed calls.
    limit = authed_client.get("daily_request_limit", 0)
    used = authed_client.get("daily_requests_used", 0)
    if not isinstance(limit, int) or limit < 0:
        _audit(client_id, api_key, 500, "VALIDATION_ERROR", meta={"reason": "bad_client_limit"})
        return _err("VALIDATION_ERROR", "Client configuration invalid: daily_request_limit must be >= 0.")
    if not isinstance(used, int) or used < 0:
        _audit(client_id, api_key, 500, "VALIDATION_ERROR", meta={"reason": "bad_client_used"})
        return _err("VALIDATION_ERROR", "Client configuration invalid: daily_requests_used must be >= 0.")
    if limit > 0 and (used + 1) > limit:
        _audit(client_id, api_key, 429, "QUOTA_EXCEEDED", meta={"daily_request_limit": limit, "daily_requests_used": used})
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_request_limit=limit, daily_requests_used=used)

    # increment counter and persist
    authed_client["daily_requests_used"] = used + 1
    authed_client["updated_at"] = now
    # write back into original container
    if isinstance(clients, dict) and isinstance(clients.get("rows"), list):
        for i, c in enumerate(clients["rows"]):
            if isinstance(c, dict) and c.get("id") == client_id:
                clients["rows"][i] = authed_client
                break
        _save("api_clients.json", clients)
    else:
        for i, c in enumerate(clients_rows):
            if isinstance(c, dict) and c.get("id") == client_id:
                clients_rows[i] = authed_client
                break
        _save("api_clients.json", clients_rows)

    # ---- fetch search_request row (must be owned by caller) ----
    sreqs = _load("search_requests.json")
    if isinstance(sreqs, dict) and isinstance(sreqs.get("rows"), list):
        sreq_rows = sreqs.get("rows")
    elif isinstance(sreqs, list):
        sreq_rows = sreqs
    else:
        sreq_rows = []

    sreq = None
    for r in sreq_rows:
        if isinstance(r, dict) and r.get("id") == search_request_id:
            sreq = r
            break

    if sreq is None:
        _audit(client_id, api_key, 404, "NOT_FOUND", meta={"search_request_id": search_request_id})
        return _err("NOT_FOUND", "search_request_id not found.", search_request_id=search_request_id)

    if sreq.get("client_id") != client_id:
        _audit(client_id, api_key, 404, "NOT_FOUND", meta={"search_request_id": search_request_id, "reason": "not_owned"})
        return _err("NOT_FOUND", "search_request_id not found.", search_request_id=search_request_id)

    # ---- build response ----
    resp = {
        "search_request": sreq,
    }

    if include_results:
        results = _load("search_results.json")
        if isinstance(results, dict) and isinstance(results.get("rows"), list):
            res_rows = results.get("rows")
        elif isinstance(results, list):
            res_rows = results
        else:
            res_rows = []

        # collect rows for this request, sorted by rank
        sreq_results = [x for x in res_rows if isinstance(x, dict) and x.get("search_request_id") == search_request_id]
        sreq_results.sort(key=lambda x: (x.get("rank") if isinstance(x.get("rank"), int) else 10**9, x.get("id", "")))

        # preload preprints
        preprints = _load("preprints.json")
        if isinstance(preprints, dict) and isinstance(preprints.get("rows"), list):
            pp_rows = preprints.get("rows")
        elif isinstance(preprints, list):
            pp_rows = preprints
        else:
            pp_rows = []
        pp_by_id = {}
        for p in pp_rows:
            if isinstance(p, dict) and isinstance(p.get("id"), str):
                pp_by_id[p["id"]] = p

        # include "basic preprint metadata": return the referenced preprint row if present
        enriched = []
        for x in sreq_results:
            pp = pp_by_id.get(x.get("preprint_id"))
            enriched.append({
                "search_result": x,
                "preprint": pp
            })

        resp["results"] = {
            "items": enriched,
            "total": len(enriched),
        }

    _audit(client_id, api_key, 200, None, meta={"include_results": include_results})
    return resp

