        _audit(client.get("id"), api_key_s, 429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_request_limit=limit, daily_requests_used=used)
    for i, c in enumerate(clients):
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["daily_requests_used"] = used + 1
            c["updated_at"] = now
            clients[i] = c
            _save("api_clients.json", clients)
            break

    # Query
    rows = _load("preprints.json")
    if not isinstance(rows, list):
        rows = []

    qlc = q.strip().lower() if isinstance(q, str) and q.strip() else None
    doi_s = doi.strip() if isinstance(doi, str) else None
    cat_s = category.strip() if isinstance(category, str) else None

    out = []
    for p in rows:
        if not isinstance(p, dict):
            continue
        if status is not None and p.get("status") != status:
            continue
        if doi_s is not None and p.get("doi") != doi_s:
            continue
        if server is not None and p.get("server") != server:
            continue
        if cat_s is not None and p.get("category") != cat_s:
            continue
        if qlc is not None:
            title_txt = (p.get("title") or "")
            if not isinstance(title_txt, str) or qlc not in title_txt.lower():
                continue
        out.append(p)

    out.sort(key=lambda p: (p.get("updated_at") or p.get("created_at") or "", p.get("doi") or ""), reverse=True)

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = out[start:end]
    has_more = end < total

    _audit(client.get("id"), api_key_s, 200, None)
    return {"items": page_rows, "page": page, "page_size": page_size, "total": total, "has_more": has_more}

