    def _audit(client_id, credential, http_status, error_code=None):
        _ensure_logs()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update_preprint_status",
            "tool_name": "update_preprint_status",
            "client_id": client_id,
            "credential": credential,
            "status": http_status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000)
        })
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _audit(None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(doi, str) or not doi.strip() or "/" not in doi:
        _audit(None, api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "doi must look like a DOI (must contain '/')", field="doi")
    if status not in ("active", "tombstoned"):
        _audit(None, api_key, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, tombstoned", field="status")

    # Authenticate (do NOT hash/verify against stored hash; stored api_key_hash is client-visible here)
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    api_key_s = api_key.strip()
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key_s or c.get("api_key_hash") == api_key_s:
            client = c
            break
    if not client:
        _audit(None, api_key_s, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid api_key")
    if client.get("status") in ("suspended", "deleted"):
        _audit(client.get("id"), api_key_s, 403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", f"Client is {client.get('status')} and cannot perform this operation.")

    # Quota
    limit = client.get("daily_request_limit")
    used = client.get("daily_requests_used")
    if not isinstance(limit, int) or limit < 0:
        _audit(client.get("id"), api_key_s, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Client daily_request_limit is invalid.")
    if not isinstance(used, int) or used < 0:
        used = 0
    if limit > 0 and (used + 1) > limit:
        _audit(client.get("id"), api_key_s, 429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_request_limit=limit, daily_requests_used=used)

    # Load and mutate preprint
    doi_s = doi.strip()
    preprints = _load("preprints.json")
    if not isinstance(preprints, list):
        preprints = []
    idx = None
    for i, p in enumerate(preprints):
        if isinstance(p, dict) and p.get("doi") == doi_s:
            idx = i
            break
    if idx is None:
        _audit(client.get("id"), api_key_s, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Preprint not found for given DOI.")

    current = preprints[idx].get("status")
    if current not in ("active", "tombstoned"):
        _audit(client.get("id"), api_key_s, 409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Preprint has invalid current status '{current}'.")

    # Enforce lifecycle transitions
    allowed = {"active": {"tombstoned"}, "tombstoned": {"active"}}
    if status == current:
        # idempotent: still "effect" is no-op; return current without rewriting quota? But quota already consumed; that's ok.
        _audit(client.get("id"), api_key_s, 200, None)
        return {"preprint": preprints[idx], "changed": False}

    if status not in allowed.get(current, set()):
        _audit(client.get("id"), api_key_s, 409, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Illegal status transition {current} -> {status}.")

    # Persist quota increment (only after we know we'll mutate)
    for i, c in enumerate(clients):
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["daily_requests_used"] = (used + 1) if isinstance(used, int) else 1
            c["updated_at"] = now
            clients[i] = c
            _save("api_clients.json", clients)
            break

    # Apply mutation
    p = preprints[idx]
    p["status"] = status
    p["updated_at"] = now
    preprints[idx] = p
    _save("preprints.json", preprints)

    _audit(client.get("id"), api_key_s, 200, None)
    return {"preprint": p, "changed": True}
